37	+/**
38	+ * Every window this interface is held to.
39	+ *
40	+ * The whole of it was measured against the first; the other two are the two
41	+ * laptop screens a reviewer is most likely to open it on, and every layout
42	+ * defect the interface audit found showed up at one of them and not at 1600.
43	+ */
44	+const WINDOWS = [
45	+  { width: 1600, height: 1000 },
46	+  { width: 1440, height: 900 },
47	+  { width: 1280, height: 800 },
48	+] as const;
49	+
50	+/**
51	+ * Every control in the panel beside the map is whole, and inside the panel.
52	+ *
53	+ * **This is a geometric assertion and never a picture.** A stored screenshot
54	+ * over a canvas with a background-threaded layout engine, two variable fonts and
55	+ * an arrival animation is a flake generator, and this project has already paid
56	+ * for chasing flakes. What it asserts instead is the thing every layout defect
57	+ * the audit found had in common: something in the panel was cut off by a box
58	+ * around it.
59	+ *
60	+ * **Scrolled out of view is allowed; clipped is not.** The panel scrolls as one
61	+ * and draws a rule at whichever edge has more beyond it, so a control below the
62	+ * fold is a control a reader can reach. What may never happen is a control
63	+ * outside the panel's own scrollable content — cut off by a sibling that scrolls
64	+ * on its own, or running past the panel's left or right edge, where no amount of
65	+ * scrolling brings it back.
66	+ *
67	+ * Every control is read in the page rather than one at a time over the wire,
68	+ * because two hundred round trips at three window sizes is a minute of waiting
69	+ * and every one of them would be reading a different moment.
70	+ *
71	+ * @param page The page the map is on.
72	+ */
73	+async function everyControlInThePanelIsWhole(page: Page): Promise<void> {
74	+  await expect
75	+    .poll(
76	+      () =>
77	+        page.evaluate(() => {
78	+          const dock = document.querySelector<HTMLElement>(".dock");
79	+          if (dock === null) {
80	+            return ["there is no panel beside the map"];
81	+          }
82	+          const panel = dock.getBoundingClientRect();
83	+          const controls = dock.querySelectorAll<HTMLElement>("button, a, input");
84	+          if (controls.length === 0) {
85	+            return ["the panel beside the map holds no controls at all"];
86	+          }
87	+          const wrong: string[] = [];
88	+          for (const control of controls) {
89	+            const name = (control.getAttribute("aria-label") ?? control.textContent ?? "")
90	+              .replace(/\s+/g, " ")
91	+              .trim()
92	+              .slice(0, 60);
93	+            const box = control.getBoundingClientRect();
94	+            if (box.width === 0 || box.height === 0) {
95	+              wrong.push(`"${name}" is drawn at no size at all`);
96	+              continue;
97	+            }
98	+            // Sideways there is nowhere to go: the panel does not scroll that
99	+            // way, so anything past either edge is gone for good.
100	+            if (box.left < panel.left - 1 || box.right > panel.right + 1) {
101	+              wrong.push(
102	+                `"${name}" runs from ${Math.round(box.left)} to ${Math.round(box.right)}, ` +
103	+                  `outside the panel's ${Math.round(panel.left)} to ${Math.round(panel.right)}`,
104	+              );
105	+            }
106	+            // And down the page, measured against the panel's own content
107	+            // rather than against what is on the glass — a control below the
108	+            // fold is fine, and one outside the content is not reachable at all.
109	+            const top = box.top - panel.top + dock.scrollTop;
110	+            const bottom = top + box.height;
111	+            if (top < -1 || bottom > dock.scrollHeight + 1) {
112	+              wrong.push(
113	+                `"${name}" sits from ${Math.round(top)} to ${Math.round(bottom)} in a panel ` +
114	+                  `holding ${dock.scrollHeight} pixels of content`,
115	+              );
116	+            }
117	+          }
118	+          return wrong;
119	+        }),
120	+      { timeout: 15_000, message: "the panel never settled with every control inside it" },
121	+    )
122	+    .toEqual([]);
123	+}
124	+
125	+/**
126	+ * The map read as a list is a list of sentences, not a list of words.
127	+ *
128	+ * **The defect this catches is a column, not a font.** An outline item is a grid
129	+ * row, and a grid row whose text track has collapsed wraps one word to a line —
130	+ * which turns a seven-claim map into a tree taller than the window and makes the
131	+ * no-picture route, the accessibility story, unusable. A third of the outline's
132	+ * own width is nowhere near a sentence and far away from two and a half
133	+ * characters, so it catches the collapse without pinning a layout.
134	+ *
135	+ * @param page The page the outline is on.
136	+ */
137	+async function everyOutlineItemIsASentenceWide(page: Page): Promise<void> {
138	+  await expect
139	+    .poll(
140	+      () =>
141	+        page.evaluate(() => {
142	+          const outline = document.querySelector<HTMLElement>(".outline");
143	+          if (outline === null) {
144	+            return ["the map is not being read as a list"];
145	+          }
146	+          const room = outline.clientWidth;
147	+          const sentences = outline.querySelectorAll<HTMLElement>(".outline__sentence");
148	+          if (sentences.length === 0) {
149	+            return ["the map read as a list has no items in it"];
150	+          }
151	+          const thin: string[] = [];
152	+          for (const sentence of sentences) {
153	+            const width = sentence.getBoundingClientRect().width;
154	+            if (width < room / 3) {
155	+              thin.push(
156	+                `an item is ${Math.round(width)} wide in an outline of ${Math.round(room)}`,
157	+              );
158	+            }
159	+          }
160	+          return thin;
161	+        }),
162	+      { timeout: 15_000, message: "the outline never settled at a readable width" },
163	+    )
164	+    .toEqual([]);
165	+}
