167	+/**
168	+ * Open the stored map and fold the strike branch onto it, with the mouse and
169	+ * the palette, and wait until the engine has answered.
170	+ *
171	+ * @param page The page to do it on.
172	+ */
173	+async function theStoredMapWithTheStrikeBranch(page: Page): Promise<void> {
174	+  await page.goto("/");
