186	+  // The engine has answered when the map says what the branch did, with the
187	+  // counts in it — before that the panel is still holding the answer to the
188	+  // question before this one.
189	+  await waitForTheAnswer(
190	+    page,
191	+    "Branch created. One claim added, six claims moved, one supposition retracted.",
192	+  );
193	+}
