200	+for (const window of WINDOWS) {
201	+  test(`test_nothing_in_the_panel_is_cut_off_at_${window.width}_by_${window.height}`, async ({
202	+    page,
203	+  }) => {
204	+    // Three window sizes, a branch, an engine answer and two states of the
205	+    // panel: longer than the walk the other tests take.
206	+    test.setTimeout(120_000);
207	+    await page.setViewportSize({ width: window.width, height: window.height });
208	+    await theStoredMapWithTheStrikeBranch(page);
209	+
210	+    // Five sections, and the panel at its fullest: your branches, the change
211	+    // list, the panel that says why a number is what it is — and, opened from
212	+    // the Inspector's own head with the mouse, the things you can do to a claim.
213	+    await page.locator('.react-flow__node[data-id="B"]').click();
214	+    const wayIn = page.getByRole("button", { name: "Change this claim" });
215	+    await expect(wayIn).toBeVisible();
216	+    await wayIn.click();
217	+    // Which claim the operations are open on, read off the panel's own mark
218	+    // rather than off its sentence: matching a sentence is testing the copy.
219	+    await expect(page.locator('.intervene[data-about="B"]')).toBeVisible();
220	+    await everyControlInThePanelIsWhole(page);
221	+
222	+    // And the field that opens inside it, which is the widest thing the panel
223	+    // ever holds.
224	+    await page.getByRole("button", { name: /^My own number/ }).click();
225	+    await expect(page.getByLabel(/Your likelihood/)).toBeVisible();
226	+    await everyControlInThePanelIsWhole(page);
227	+
228	+    // Then the same map read as a list, which is the panel's other state and
229	+    // the one the no-picture route depends on. `O` is a map key, so the
230	+    // keyboard goes back on the map first — the press is otherwise the
231	+    // button's, which is the product's rule rather than this test's
232	+    // convenience.
233	+    await standOn(page, "B");
234	+    await page.keyboard.press("O");
235	+    await expect(page.getByRole("tree")).toBeVisible();
236	+    await everyOutlineItemIsASentenceWide(page);
237	+    await everyControlInThePanelIsWhole(page);
238	+  });
239	+}
