241	+/**
242	+ * The whole of the brief's core interaction, with the mouse and nothing else.
243	+ *
244	+ * **The keyboard walk above is the other half of this claim, not a substitute
245	+ * for it.** The panel of operations used to open from `E` and from the command
246	+ * palette and from nowhere else, so somebody working this screen by pointing at
247	+ * things could click every tile, read the whole argument and never find a verb
248	+ * on it. Not one key is pressed below.
249	+ */
250	+test("test_the_mouse_alone_reaches_the_six_things_you_can_do", async ({ page }) => {
251	+  await page.goto("/");
252	+  await page
253	+    .getByRole("button", { name: /Strait of Hormuz/ })
254	+    .first()
255	+    .click();
256	+  await waitForTheLayout(page, 7);
257	+
258	+  // A claim, chosen by pointing at it. No branch is open, so the edit below
259	+  // starts one of the reader's own — which is this product's own rule, and is
260	+  // what makes this a journey rather than a button press.
261	+  await page.locator('.react-flow__node[data-id="B"]').click();
262	+
263	+  // The way in, in the panel's head, in the vocabulary's own words. It is not
264	+  // there at all until something is selected, so waiting for it is waiting for
265	+  // the pointer to have landed.
266	+  const wayIn = page.getByRole("button", { name: "Change this claim" });
267	+  await expect(wayIn).toBeVisible();
268	+  await wayIn.click();
269	+
270	+  // **Which claim the operations are open on is read off the panel's own mark,
271	+  // never off its sentence.** The panel prints claims in their own words and
272	+  // arrows as the two claims at their ends, and a test that matched those words
273	+  // would be a test of the copy — which is how one end-to-end test came to fail
274	+  // on every cold run after a sentence was improved.
275	+  const operations = page.locator('.intervene[data-about="B"]');
276	+  await expect(operations).toBeVisible();
277	+  // And the difference between the two that are easiest to confuse is on the
278	+  // screen before the choice rather than after it.
279	+  await expect(operations).toContainText("Take this as given, and do not tell me what caused it");
280	+  await expect(operations).toContainText("This is news — update what came before it too");
281	+
282	+  await operations.getByRole("button", { name: /^Suppose this is true/ }).click();
283	+
284	+  // **The branch gained the edit.** It is listed by the button that made it,
285	+  // with the badge that button earns, on a branch that did not exist a moment
286	+  // ago — read off the panel rather than out of this file.
287	+  const branches = page.locator(".branch-panel");
288	+  await expect(branches).toContainText("Your own branch");
289	+  await expect(branches).toContainText("1 edit");
290	+  await expect(branches.locator(".branch-panel__button-name")).toHaveText("Suppose this is true");
291	+  await expect(branches.locator(".branch-panel__badge")).toHaveText(/^Supposed · /);
292	+
293	+  // And the map says out loud that a branch was created, for a reader who is
294	+  // not looking at the picture.
295	+  await expect(page.locator(".map-live")).toContainText("Branch created.");
296	+});
