--- a/frontend/src/components/outline.css
+++ b/frontend/src/components/outline.css
@@ -54,10 +54,24 @@
   padding-left: var(--space-6);
 }

+/* One sentence across the whole width of the panel.
+ *
+ * **It used to be two columns, `2.4em 1fr`, and the second one was empty.** The
+ * first column held the claim's letter on the map; that letter was taken off
+ * every surface, because on a generated map an identifier is twenty-six
+ * characters nobody can read (`world/naming.ts`). The track it sat in stayed. A
+ * grid places its one remaining child in the *first* track, so every sentence in
+ * this list was being wrapped inside two and a half characters — one word a
+ * line, and a claim eight hundred pixels tall in a nine-hundred-pixel window.
+ *
+ * So there is one column, and it is `minmax(0, 1fr)` rather than `1fr`. `1fr`
+ * alone is `minmax(auto, 1fr)`, whose floor is the longest unbreakable word in
+ * the sentence — one long address in a claim and the column would be wider than
+ * the panel, taking the row's right-hand edge off the screen. With the floor at
+ * zero the row is exactly as wide as the panel, whatever is in it. */
 .outline__line {
   display: grid;
-  grid-template-columns: 2.4em 1fr;
-  column-gap: var(--space-1);
+  grid-template-columns: minmax(0, 1fr);
   width: 100%;
   margin: 0;
   padding: var(--space-hair) var(--space-1);
@@ -83,8 +97,10 @@
   border-color: var(--accent);
 }

-.outline__id {
-  font-family: var(--font-mono);
-  font-weight: var(--weight-semibold);
-  color: var(--text-muted);
+/* The sentence itself. Its own floor is zero for the same reason the column's
+ * is: a grid child is `min-width: auto` by default, which is the width of its
+ * longest unbreakable word, and that floor would push the row past the panel's
+ * edge however wide the track around it was allowed to be. */
+.outline__sentence {
+  min-width: 0;
 }
