244	/**
245	 * Every control in the panel beside the map is whole, and inside the panel.
246	 *
247	 * **This is a geometric assertion and never a picture.** A stored screenshot
248	 * over a canvas with a background-threaded layout engine, two variable fonts and
249	 * an arrival animation is a flake generator, and this project has already paid
250	 * for chasing flakes. What it asserts instead is the thing every layout defect
251	 * the audit found had in common: something in the panel was cut off by a box
252	 * around it.
253	 *
254	 * **Scrolled out of view is allowed; clipped is not.** The panel scrolls as one
255	 * and draws a rule at whichever edge has more beyond it, so a control below the
256	 * fold is a control a reader can reach. What may never happen is a control
257	 * outside the panel's own scrollable content — cut off by a sibling that scrolls
258	 * on its own, or running past the panel's left or right edge, where no amount of
259	 * scrolling brings it back.
260	 *
261	 * Every control is read in the page rather than one at a time over the wire,
262	 * because two hundred round trips at three window sizes is a minute of waiting
263	 * and every one of them would be reading a different moment.
264	 *
265	 * @param page The page the map is on.
266	 */
267	async function everyControlInThePanelIsWhole(page: Page): Promise<void> {
268	  await expect
269	    .poll(
270	      () =>
271	        page.evaluate(() => {
272	          const dock = document.querySelector<HTMLElement>(".dock");
273	          if (dock === null) {
274	            return ["there is no panel beside the map"];
275	          }
276	          const panel = dock.getBoundingClientRect();
277	          const controls = dock.querySelectorAll<HTMLElement>("button, a, input");
278	          if (controls.length === 0) {
279	            return ["the panel beside the map holds no controls at all"];
280	          }
281	          const wrong: string[] = [];
282	          for (const control of controls) {
283	            const name = (control.getAttribute("aria-label") ?? control.textContent ?? "")
284	              .replace(/\s+/g, " ")
285	              .trim()
286	              .slice(0, 60);
287	            const box = control.getBoundingClientRect();
288	            if (box.width === 0 || box.height === 0) {
289	              wrong.push(`"${name}" is drawn at no size at all`);
290	              continue;
291	            }
292	            // Sideways there is nowhere to go: the panel does not scroll that
293	            // way, so anything past either edge is gone for good.
294	            if (box.left < panel.left - 1 || box.right > panel.right + 1) {
295	              wrong.push(
296	                `"${name}" runs from ${Math.round(box.left)} to ${Math.round(box.right)}, ` +
297	                  `outside the panel's ${Math.round(panel.left)} to ${Math.round(panel.right)}`,
298	              );
299	            }
300	            // And down the page, measured against the panel's own content
301	            // rather than against what is on the glass — a control below the
302	            // fold is fine, and one outside the content is not reachable at all.
303	            const top = box.top - panel.top + dock.scrollTop;
304	            const bottom = top + box.height;
305	            if (top < -1 || bottom > dock.scrollHeight + 1) {
306	              wrong.push(
307	                `"${name}" sits from ${Math.round(top)} to ${Math.round(bottom)} in a panel ` +
308	                  `holding ${dock.scrollHeight} pixels of content`,
309	              );
310	            }
311	          }
312	          return wrong;
313	        }),
314	      { timeout: 15_000, message: "the panel never settled with every control inside it" },
315	    )
316	    .toEqual([]);
317	}
