332	  await expect
333	    .poll(
334	      () =>
335	        page.evaluate(() => {
336	          const outline = document.querySelector<HTMLElement>(".outline");
337	          if (outline === null) {
338	            return ["the map is not being read as a list"];
339	          }
340	          const room = outline.clientWidth;
341	          const sentences = outline.querySelectorAll<HTMLElement>(".outline__sentence");
342	          if (sentences.length === 0) {
343	            return ["the map read as a list has no items in it"];
344	          }
345	          const thin: string[] = [];
346	          for (const sentence of sentences) {
347	            const width = sentence.getBoundingClientRect().width;
348	            if (width < room / 3) {
349	              thin.push(
350	                `an item is ${Math.round(width)} wide in an outline of ${Math.round(room)}`,
351	              );
352	            }
353	          }
354	          return thin;
355	        }),
356	      { timeout: 15_000, message: "the outline never settled at a readable width" },
357	    )
358	    .toEqual([]);
359	}
