377	  await page.keyboard.type("Hormuz opens");
378	  await page.keyboard.press("Enter");
379	  await waitForTheBranch(page, "Hormuz opens, then Iran is struck", 8);
380	  // The engine has answered when the map says what the branch did, with the
381	  // counts in it — before that the panel is still holding the answer to the
