403	
404	    // Five sections, and the panel at its fullest: your branches, the change
405	    // list, the panel that says why a number is what it is — and, opened from
406	    // the Inspector's own head with the mouse, the things you can do to a claim.
407	    await page.locator('.react-flow__node[data-id="B"]').click();
408	    const wayIn = page.getByRole("button", { name: "Change this claim" });
409	    await expect(wayIn).toBeVisible();
410	    await wayIn.click();
411	    // Which claim the operations are open on, read off the panel's own mark
412	    // rather than off its sentence: matching a sentence is testing the copy.
413	    await expect(page.locator('.intervene[data-about="B"]')).toBeVisible();
414	    await everyControlInThePanelIsWhole(page);
415	
416	    // And the field that opens inside it, which is the widest thing the panel
417	    // ever holds.
418	    await page.getByRole("button", { name: /^My own number/ }).click();
419	    await expect(page.getByLabel(/Your likelihood/)).toBeVisible();
420	    await everyControlInThePanelIsWhole(page);
