422	    // Then the same map read as a list, which is the panel's other state and
423	    // the one the no-picture route depends on. `O` is a map key, so the
424	    // keyboard goes back on the map first — the press is otherwise the
425	    // button's, which is the product's rule rather than this test's
426	    // convenience.
427	    await standOn(page, "B");
428	    await page.keyboard.press("O");
429	    await expect(page.getByRole("tree")).toBeVisible();
430	    await everyOutlineItemIsASentenceWide(page);
431	    await everyControlInThePanelIsWhole(page);
432	  });
433	}
