435	/**
436	 * The whole of the brief's core interaction, with the mouse and nothing else.
437	 *
438	 * **The keyboard walk above is the other half of this claim, not a substitute
439	 * for it.** The panel of operations used to open from `E` and from the command
440	 * palette and from nowhere else, so somebody working this screen by pointing at
441	 * things could click every tile, read the whole argument and never find a verb
442	 * on it. Not one key is pressed below.
443	 */
444	test("test_the_mouse_alone_reaches_the_six_things_you_can_do", async ({ page }) => {
445	  await page.goto("/");
446	  await page
447	    .getByRole("button", { name: /Strait of Hormuz/ })
448	    .first()
449	    .click();
450	  await waitForTheLayout(page, 7);
451	
452	  // A claim, chosen by pointing at it. No branch is open, so the edit below
453	  // starts one of the reader's own — which is this product's own rule, and is
454	  // what makes this a journey rather than a button press.
455	  await page.locator('.react-flow__node[data-id="B"]').click();
456	
457	  // The way in, in the panel's head, in the vocabulary's own words. It is not
458	  // there at all until something is selected, so waiting for it is waiting for
459	  // the pointer to have landed.
460	  const wayIn = page.getByRole("button", { name: "Change this claim" });
461	  await expect(wayIn).toBeVisible();
462	  await wayIn.click();
463	
464	  // **Which claim the operations are open on is read off the panel's own mark,
465	  // never off its sentence.** The panel prints claims in their own words and
466	  // arrows as the two claims at their ends, and a test that matched those words
467	  // would be a test of the copy — which is how one end-to-end test came to fail
468	  // on every cold run after a sentence was improved.
469	  const operations = page.locator('.intervene[data-about="B"]');
470	  await expect(operations).toBeVisible();
471	  // And the difference between the two that are easiest to confuse is on the
472	  // screen before the choice rather than after it.
473	  await expect(operations).toContainText("Take this as given, and do not tell me what caused it");
474	  await expect(operations).toContainText("This is news — update what came before it too");
475	
476	  await operations.getByRole("button", { name: /^Suppose this is true/ }).click();
477	
478	  // **The branch gained the edit.** It is listed by the button that made it,
479	  // with the badge that button earns, on a branch that did not exist a moment
480	  // ago — read off the panel rather than out of this file.
481	  const branches = page.locator(".branch-panel");
482	  await expect(branches).toContainText("Your own branch");
483	  await expect(branches).toContainText("1 edit");
484	  await expect(branches.locator(".branch-panel__button-name")).toHaveText("Suppose this is true");
485	  await expect(branches.locator(".branch-panel__badge")).toHaveText(/^Supposed · /);
486	
487	  // And the map says out loud that a branch was created, for a reader who is
488	  // not looking at the picture.
489	  await expect(page.locator(".map-live")).toContainText("Branch created.");
490	});
491	
492	/**
493	 * What the hypothesis's tile must read, word for word, once the strike lands.
494	 *
495	 * Two badges with an arrow drawn between them, which is what makes the rule read
496	 * as a sequence: you supposed the strait reopens, and a later edit pushed it back
497	 * down. Each badge also carries the sentence behind it for a reader who is not
498	 * looking at the tile, and that sentence is not part of what is drawn.
499	 */

