        </p>
      )
    }
    map={
      <MapCanvas
        world={world}
        selection={selection}
        onSelect={setSelection}
        focused={focused}
        onFocused={setFocused}
        heights={heights}
        mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
        keys={keys}
        onStatus={setStatus}
