100	 * the one screen this product cannot afford to be caught out on is the one that
101	 * exists to say what this copy can honestly do.
102	 *
103	 * @param day The day the recordings were made.
104	 */
105	export function keylessSentence(day: string): string {
106	  return `No model key configured — these four run from recordings made on ${day}.`;
107	}
108	
109	/**
110	 * What this copy can play, in one or two sentences, and always true.
111	 *
112	 * Four shapes, and the first is record 0012's own words. The others say the same
113	 * kind of thing in the same voice: how many of the four can be played, how many
114	 * cannot, and the day — the **oldest** day, where there is more than one, so the
115	 * sentence is never more current than the oldest thing it describes.
116	 *
117	 * @param days The day each playable example was recorded on, in any order.
118	 * @param outOf How many sentences the screen offers altogether.
119	 */
120	export function whatThisCopyCanPlay(days: readonly string[], outOf: number): string | null {
121	  if (days.length === 0) {
122	    return null;
123	  }
124	  const sorted = [...days].sort();
125	  const oldest = sorted[0] as string;
126	  const allOfThem = days.length === outOf;
127	  const oneDay = sorted[sorted.length - 1] === oldest;
128	
129	  if (allOfThem && oneDay) {
130	    return keylessSentence(oldest);
131	  }
132	  if (allOfThem) {
133	    return (
134	      `No model key configured — these ${countInWords(outOf)} run from recordings, the oldest ` +
135	      `made on ${oldest}.`
136	    );
137	  }
138	  const rest = outOf - days.length;
139	  const canPlay = days.length === 1 ? "runs" : "run";
140	  const cannot = rest === 1 ? "has" : "have";
141	  const theRest = rest === 1 ? "the other one" : `the other ${countInWords(rest)}`;
142	  const when = oneDay ? `made on ${oldest}` : `the oldest made on ${oldest}`;
143	  return (
144	    `No model key configured — ${countInWords(days.length)} of these ${countInWords(outOf)} ` +
145	    `${canPlay} from recordings, ${when}; ${theRest} ${cannot} nothing recorded yet.`
146	  );
147	}
148	
149	/**
150	 * What this copy can do with one of the brief's sentences.
151	 *
152	 * Four, and the last two never draw a card. **`not-yet` draws nothing at all**:
153	 * an example this copy can neither run nor play is not a card a reader can take
154	 * up, and three of them side by side under a heading that offers to build you a
155	 * map is a graveyard with a door in it. What is left of them is one quiet line
156	 * under the cards that do work, naming how many there are and why — which is the
157	 * same sentence that was already printed there, in `whatThisCopyCanPlay`.
158	 *
159	 * **`asking` is the state before the server has answered**, and it draws the
160	 * sentence with one line saying what is being waited for. Without it the screen
161	 * asserts *no model key* in the moment before it has been told anything, which
162	 * is a state nobody can trace to an input.
163	 */
164	type CardState = "live" | "replay" | "not-yet" | "asking";
165	
166	/** What the launchpad needs to draw itself. */
167	export interface LaunchpadProps {
168	  /**
169	   * The stored examples the server ships with, or null while the answer is still
170	   * on its way.
171	   */
172	  readonly examples: readonly FixtureSummary[] | null;
173	  /** Why the list could not be read, if it could not be. */
174	  readonly failure: string | null;
175	  /**
176	   * What the server said about itself: whether a key is configured, and what it
177	   * can play back. Null while that answer is still on its way.
178	   */
179	  readonly readiness: Readiness | null;
180	  /** Open a stored example's map, already drawn. */
181	  readonly onOpen: (id: string) => void;
182	  /** Build a map from a sentence. */
183	  readonly onBuild: (asked: Asked) => void;
184	}
185	
186	/** The first screen. */
187	export function Launchpad({ examples, failure, readiness, onOpen, onBuild }: LaunchpadProps) {
188	  // The two facts this screen reads, and the one it deliberately does not.
189	  const hasKey = readiness?.model_key_present === true;
190	  const recorded = new Map(
191	    (readiness?.replayable ?? []).map((one) => [one.example, one.recording_date]),
192	  );
193	  // The day each of the four sentences was recorded on, for the ones that were.
194	  // Read off the cards rather than off the whole answer, so a recording of
195	  // something this screen does not offer cannot make its sentence wrong.
196	  const playable = STARTING_SENTENCES.map((one) => recorded.get(one.example)).filter(
197	    (day): day is string => day !== undefined,
198	  );
199	  const canPlay = whatThisCopyCanPlay(playable, STARTING_SENTENCES.length);
200	  const stateOf = (example: string): CardState =>
201	    readiness === null ? "asking" : hasKey ? "live" : recorded.has(example) ? "replay" : "not-yet";
202	  // The sentences that get a card: the ones this copy can actually do something
203	  // with, and — while the server is still being asked — all of them, because
204	  // nothing is yet known about any of them. The rest are named in one line under
205	  // the cards rather than drawn as rows nobody can press.
206	  const shown = STARTING_SENTENCES.filter((one) => stateOf(one.example) !== "not-yet");
207	
208	  return (
209	    <div className="launchpad">
210	      <section className="launchpad__doors" aria-labelledby="doors-heading">
211	        <h2 className="section-heading" id="doors-heading">
212	          Two ways in
213	        </h2>
214	        <ul className="doors">
215	          {DOORS.map((door) => (
216	            <li className="door" key={door.name}>
217	              <span className="door__name">{door.name}</span>
218	              <span className="door__line">{door.line}</span>
219	            </li>

